css:
.knowbasesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7edf5;
    background: linear-gradient(160deg, #0c1422 0%, #111d31 60%, #0a1320 100%);
    border-radius: 18px;
}

.knowbasesim-container * {
    box-sizing: border-box;
}

.knowbasesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0f2138 0%, #16345a 55%, #1f5fa8 100%);
    color: #f3f8ff;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #234468;
    box-shadow: 0 12px 34px rgba(4, 12, 24, 0.55);
}

.knowbasesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.knowbasesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #8fd0ff;
    background: rgba(143, 208, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
    border: 1px solid rgba(143, 208, 255, 0.25);
}

.knowbasesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfe0f2;
}

.knowbasesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebfd4;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.knowbasesim-period-counter #currentDay,
.knowbasesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #6fc3ff;
}

.knowbasesim-round-name {
    background: #1a3252;
    color: #8fd0ff;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid #2a4a72;
}

.knowbasesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffcaa3;
    background: rgba(199, 96, 38, 0.18);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(199, 96, 38, 0.4);
}

.knowbasesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.knowbasesim-status-card {
    background: #13233c;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #21385a;
    box-shadow: 0 4px 16px rgba(4, 12, 24, 0.4);
    border-top: 4px solid #1f5fa8;
}

.knowbasesim-card-breadth { border-top-color: #2f9e8f; }
.knowbasesim-card-depth { border-top-color: #3d7ad6; }
.knowbasesim-card-output { border-top-color: #6f8cf0; }
.knowbasesim-card-efficiency { border-top-color: #d8a33a; }

.knowbasesim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8499b5;
}

.knowbasesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f3f8ff;
}

.knowbasesim-card-breadth .knowbasesim-value { color: #43c9b6; }
.knowbasesim-card-depth .knowbasesim-value { color: #6aa8ff; }
.knowbasesim-card-output .knowbasesim-value { color: #93a9ff; }
.knowbasesim-card-efficiency .knowbasesim-value { color: #f0bf57; }

.knowbasesim-sublabel {
    font-size: 0.75rem;
    color: #7d92ae;
    line-height: 1.35;
}

.knowbasesim-card-output.knowbasesim-output-won { border-top-color: #3fd27a; }
.knowbasesim-card-output.knowbasesim-output-won .knowbasesim-value { color: #5fe293; }
.knowbasesim-card-output.knowbasesim-output-lost { border-top-color: #e0584b; }
.knowbasesim-card-output.knowbasesim-output-lost .knowbasesim-value { color: #ff7a6e; }

.knowbasesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0a1828;
    color: #dbe8f7;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #203a5c;
}

.knowbasesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #6fc3ff;
}

.knowbasesim-budget-bar.knowbasesim-budget-over #budgetDisplay {
    color: #ff7a6e;
}

.knowbasesim-briefing {
    display: flex;
    gap: 14px;
    background: #13233c;
    border-left: 5px solid #1f5fa8;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 16px rgba(4, 12, 24, 0.35);
}

.knowbasesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.knowbasesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #8fd0ff;
    margin-bottom: 6px;
}

.knowbasesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cad9ee;
}

.knowbasesim-briefing-text strong { color: #5fe293; }
.knowbasesim-briefing-text em { color: #ffc1ad; font-style: italic; }

.knowbasesim-controls {
    background: #13233c;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #21385a;
    box-shadow: 0 4px 16px rgba(4, 12, 24, 0.4);
}

.knowbasesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f3f8ff;
    border-bottom: 2px solid #21385a;
    padding-bottom: 8px;
}

.knowbasesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #bcd0ea;
    margin: 14px 0 6px;
}

.knowbasesim-container select,
.knowbasesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2c486f;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0d1a2c;
    color: #e7edf5;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.knowbasesim-container select:focus,
.knowbasesim-container input[type="number"]:focus {
    outline: none;
    border-color: #3d7ad6;
    box-shadow: 0 0 0 3px rgba(61, 122, 214, 0.25);
}

.knowbasesim-container select option {
    background-color: #0d1a2c;
    color: #e7edf5;
}

.knowbasesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #3d7ad6;
}

.knowbasesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #8fd0ff;
    margin-top: 4px;
}

.knowbasesim-range-readout span:last-child {
    color: #5fe293;
    font-weight: 800;
}

.knowbasesim-hint {
    font-size: 0.8rem;
    color: #7d92ae;
    margin-top: 4px;
    line-height: 1.4;
}

.knowbasesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.knowbasesim-container .btn-primary {
    background: linear-gradient(135deg, #1f5fa8 0%, #2f9e8f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 18px rgba(31, 95, 168, 0.35);
}

.knowbasesim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.knowbasesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2c486f;
    color: #8499b5;
    background: transparent;
}

.knowbasesim-coach {
    background: #0a1828;
    color: #dbe8f7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #203a5c;
    box-shadow: 0 6px 20px rgba(4, 12, 24, 0.45);
}

.knowbasesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #6fc3ff;
    margin-bottom: 8px;
}

.knowbasesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.knowbasesim-coach-body strong { color: #5fe293; }
.knowbasesim-coach-body em { color: #ffc1ad; font-style: italic; }

.knowbasesim-history,
.knowbasesim-chart {
    background: #13233c;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #21385a;
    box-shadow: 0 4px 16px rgba(4, 12, 24, 0.4);
}

.knowbasesim-history h3,
.knowbasesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #8fd0ff;
}

.knowbasesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cad9ee;
}

.knowbasesim-container table#usfHistoryTable th {
    background: #0f2138;
    color: #8fd0ff;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #21385a;
}

.knowbasesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1c3050;
}

.knowbasesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #102036;
}

.knowbasesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .knowbasesim-container {
        padding: 14px;
    }
    .knowbasesim-header h1 {
        font-size: 1.7rem;
    }
    .knowbasesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .knowbasesim-value {
        font-size: 2rem;
    }
    .knowbasesim-clock {
        margin-left: 0;
    }
    .knowbasesim-period-counter {
        font-size: 0.88rem;
    }
    .knowbasesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .knowbasesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.knowbasesim-completion { padding: 8px 4px 4px; }
.knowbasesim-cm-head { text-align: center; margin-bottom: 16px; }
.knowbasesim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #6fc3ff; }
.knowbasesim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #8fd0ff; }
.knowbasesim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #e7edf5; }
.knowbasesim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.knowbasesim-cm-yes { background: rgba(95,226,147,0.16); color: #5fe293; border: 1px solid rgba(95,226,147,0.45); }
.knowbasesim-cm-no { background: rgba(255,120,120,0.14); color: #ff9b9b; border: 1px solid rgba(255,120,120,0.5); }
.knowbasesim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.knowbasesim-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(111,195,255,0.08); border: 1px solid rgba(111,195,255,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.knowbasesim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #6fc3ff; }
.knowbasesim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #9fb3cc; text-transform: uppercase; letter-spacing: 0.03em; }
.knowbasesim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #e7edf5; }
.knowbasesim-cm-insights { margin: 0; padding-left: 20px; }
.knowbasesim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #cdd8ea; }

