(function() {
    'use strict';

    class KnowBaseAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Building the Knowledge Base`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (EUR, in € millions).
            this.BUDGET_CAP = 220;        // EUR 220M / 3 years — the board constraint
            this.COST_BUY_SEMI = 140;     // Eindhoven semiconductor acquisition
            this.COST_PARTNER_SEMI = 18;  // microelectronics-institute joint lab
            this.COST_PARTNER_SW = 35;    // software-controls co-development deal
            this.COST_BUY_SW = 130;       // hypothetical 2nd acquisition (unfunded, breaks budget)
            this.COST_BUILD = 25;         // organic build programme (per domain, 3-yr slice)
            this.PLATFORM_REVENUE = 410;  // EUR 410M lifetime revenue at stake
            this.WIN_THRESHOLD = 60;      // module readiness needed to win the platform

            this.START = { breadth: 42, depth: 22, output: 18 };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    breadth: this.START.breadth,
                    depth: this.START.depth,
                    output: this.START.output,
                    budgetUsed: 0,
                    absorbSpend: 0,
                    overBudget: false,
                    ipLeaked: false,
                    blackBox: false,
                    platformWon: false,
                    breadthHistory: [this.START.breadth],
                    depthHistory: [this.START.depth],
                    outputHistory: [this.START.output],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    gap: `growth`,
                    shape: `narrowdeep`,
                    urgency: 60,
                    semiMode: `buy`,
                    swMode: `partner`,
                    absorb: 30,
                    strongholds: 20,
                    posture: `hybrid`,
                    boundary: `protectjewels`,
                    absorb2: 15,
                    internalise: 60,
                    focus: `module`,
                    reallocate: `stayagile`,
                    defend: `output`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gap = document.getElementById(`gapInput`);
                const shape = document.getElementById(`shapeInput`);
                const urg = document.getElementById(`urgencyInput`);
                if (gap) decisions.gap = gap.value;
                if (shape) decisions.shape = shape.value;
                if (urg) decisions.urgency = parseInt(urg.value, 10);
                if (!Number.isFinite(decisions.urgency) || decisions.urgency < 0 || decisions.urgency > 100) {
                    warn(`warn_urgency_range`); return false;
                }
            } else if (round === 2) {
                const sm = document.getElementById(`semiModeInput`);
                const sw = document.getElementById(`swModeInput`);
                const ab = document.getElementById(`absorbInput`);
                const st = document.getElementById(`strongholdsInput`);
                if (sm) decisions.semiMode = sm.value;
                if (sw) decisions.swMode = sw.value;
                if (ab) decisions.absorb = parseFloat(ab.value);
                if (st) decisions.strongholds = parseFloat(st.value);
                if (!Number.isFinite(decisions.absorb) || decisions.absorb < 0) {
                    warn(`warn_absorb_negative`); return false;
                }
                if (!Number.isFinite(decisions.strongholds) || decisions.strongholds < 0) {
                    warn(`warn_strongholds_negative`); return false;
                }
            } else if (round === 3) {
                const po = document.getElementById(`postureInput`);
                const bo = document.getElementById(`boundaryInput`);
                const a2 = document.getElementById(`absorb2Input`);
                const it = document.getElementById(`internaliseInput`);
                if (po) decisions.posture = po.value;
                if (bo) decisions.boundary = bo.value;
                if (a2) decisions.absorb2 = parseFloat(a2.value);
                if (it) decisions.internalise = parseInt(it.value, 10);
                if (!Number.isFinite(decisions.absorb2) || decisions.absorb2 < 0) {
                    warn(`warn_absorb2_negative`); return false;
                }
                if (!Number.isFinite(decisions.internalise) || decisions.internalise < 0 || decisions.internalise > 100) {
                    warn(`warn_internalise_range`); return false;
                }
            } else if (round === 4) {
                const fo = document.getElementById(`focusInput`);
                const re = document.getElementById(`reallocateInput`);
                const de = document.getElementById(`defendInput`);
                const cv = document.getElementById(`convictionInput`);
                if (fo) decisions.focus = fo.value;
                if (re) decisions.reallocate = re.value;
                if (de) decisions.defend = de.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let breadthDelta = 0, depthDelta = 0, outputDelta = 0;
            let spend = 0, absorbSpend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose where value is migrating (semis + software), not the commoditising
                // strongholds and not a fashionable adjacency (Core Competence vs Commoditisation).
                if (d.gap === `growth`) {
                    breadthDelta += 6; depthDelta += 4; outputDelta += 4; coachKey = `coach_r1_growth`;
                } else if (d.gap === `strongholds`) {
                    breadthDelta -= 6; depthDelta -= 2; outputDelta -= 6; coachKey = `coach_r1_strongholds`;
                } else {
                    breadthDelta -= 2; outputDelta -= 8; coachKey = `coach_r1_adjacent`;
                }

                // Read the shape of the knowledge base: narrow-but-deep with dangerous gaps.
                if (d.shape === `narrowdeep`) {
                    breadthDelta += 6; depthDelta += 3;
                    if (d.gap === `growth`) coachKey = `coach_r1_sharp`;
                } else if (d.shape === `broad`) {
                    breadthDelta -= 4; outputDelta -= 4; coachKey = `coach_r1_broad`;
                } else {
                    breadthDelta -= 8; depthDelta -= 4; outputDelta -= 6; coachKey = `coach_r1_complacent`;
                }

                // Urgency: quantifying the cost of inaction against the 9-month clock.
                if (d.urgency >= 60) { outputDelta += 6; }
                else if (d.urgency <= 25) { outputDelta -= 8; coachKey = `coach_r1_lowurgency`; }

                summaryKey = (d.gap === `growth` && d.shape === `narrowdeep`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Build / Buy / Partner per competence, funded from EUR 220M, with absorptive capacity.
                absorbSpend = d.absorb;

                // --- Power semiconductors ---
                if (d.semiMode === `buy`) {
                    spend += this.COST_BUY_SEMI;
                    // Deep & fast IF absorbed; a black box if not (Common Error 2).
                    const absorbFactor = Math.max(0, Math.min(1, d.absorb / 40));
                    depthDelta += Math.round(8 + 22 * absorbFactor);
                    outputDelta += Math.round(6 + 16 * absorbFactor);
                    breadthDelta += 4;
                    if (d.absorb < 15) {
                        depthDelta -= 8; outputDelta -= 6; ds.blackBox = true; coachKey = `coach_r2_blackbox`;
                    } else {
                        coachKey = `coach_r2_buyabsorb`;
                    }
                } else if (d.semiMode === `partner`) {
                    spend += this.COST_PARTNER_SEMI;
                    // Cheap, broad, slow, non-exclusive — capital-efficient but renting a domain
                    // where value is migrating (Common Error 3).
                    breadthDelta += 10; depthDelta += 6; outputDelta += 4; coachKey = `coach_r2_rentsemis`;
                } else {
                    spend += this.COST_BUILD;
                    // 4–5 years to capability — far too slow for the 9-month clock (Common Error 1).
                    depthDelta += 4; outputDelta -= 8; coachKey = `coach_r2_buildsemis`;
                }

                // --- Embedded control software ---
                if (d.swMode === `partner`) {
                    spend += this.COST_PARTNER_SW;
                    // Fast, shared IP — a sound mode for software where speed matters most.
                    breadthDelta += 6; depthDelta += 8; outputDelta += 12;
                    if (d.semiMode === `buy`) coachKey = `coach_r2_balanced`;
                } else if (d.swMode === `build`) {
                    spend += this.COST_BUILD;
                    depthDelta += 4; outputDelta -= 8; coachKey = `coach_r2_buildsw`;
                } else {
                    spend += this.COST_BUY_SW;
                    // A second acquisition has no funded target — it breaks the budget.
                    depthDelta += 6; outputDelta += 4; coachKey = `coach_r2_buysw`;
                }

                // Absorptive capacity converts bought/partnered knowledge into real depth & output.
                if (d.absorb >= 25) { depthDelta += 8; outputDelta += 6; }
                else if (d.absorb >= 10) { depthDelta += 3; outputDelta += 2; }
                else { depthDelta -= 4; if (!ds.blackBox) coachKey = `coach_r2_noabsorb`; }
                spend += d.absorb;

                // Stronghold defence: a little is rational; over-funding a commoditising domain
                // starves the gap domains (thin spreading risk).
                spend += d.strongholds;
                if (d.strongholds > 0 && d.strongholds <= 25) {
                    breadthDelta += 2;
                } else if (d.strongholds > 25) {
                    breadthDelta += 1; outputDelta -= 4; coachKey = `coach_r2_overstronghold`;
                }

                // Critical mass vs thin spreading: partner+partner with weak absorb closes nothing.
                if (d.semiMode === `partner` && d.swMode === `partner` && d.absorb < 25) {
                    depthDelta -= 6; outputDelta -= 6; coachKey = `coach_r2_thin`;
                }

                const goodModes = (d.semiMode === `buy` && d.swMode === `partner`);
                summaryKey = (goodModes && d.absorb >= 25) ? `sum_r2_good` : (ds.blackBox ? `sum_r2_blackbox` : `sum_r2_weak`);
            } else if (round === 3) {
                // Ecosystem posture & the open/closed IP boundary (Innovation Ecosystems).
                if (d.posture === `hybrid`) {
                    breadthDelta += 10; depthDelta += 4; outputDelta += 4; coachKey = `coach_r3_hybrid`;
                } else if (d.posture === `closed`) {
                    breadthDelta -= 10; outputDelta -= 4; coachKey = `coach_r3_closed`;
                } else {
                    breadthDelta += 12; outputDelta += 2; coachKey = `coach_r3_open`;
                }

                // The open/closed boundary: protect crown jewels, open the new growth domains.
                if (d.boundary === `protectjewels`) {
                    breadthDelta += 4; depthDelta += 4;
                    if (d.posture === `hybrid`) coachKey = `coach_r3_boundary_right`;
                } else if (d.boundary === `openjewels`) {
                    // Leaking the last defensible stronghold (Common Error 4 — naive openness).
                    breadthDelta += 2; outputDelta -= 10; depthDelta -= 4; ds.ipLeaked = true; coachKey = `coach_r3_leak`;
                } else {
                    // Closing even the partnered domains starves absorptive gains.
                    breadthDelta -= 8; depthDelta -= 2; coachKey = `coach_r3_closeall`;
                }

                // If posture is fully open AND jewels are opened, the leak is severe.
                if (d.posture === `open` && d.boundary === `openjewels`) {
                    outputDelta -= 6; depthDelta -= 4; ds.ipLeaked = true; coachKey = `coach_r3_leak`;
                }

                // Absorptive capacity & internalisation convert external knowledge to capability.
                spend += d.absorb2;
                const intFactor = Math.max(0, Math.min(1, d.internalise / 100));
                depthDelta += Math.round(d.absorb2 * 0.4 * (0.5 + intFactor));
                outputDelta += Math.round(d.absorb2 * 0.3 * (0.5 + intFactor));
                if (d.internalise >= 60) { depthDelta += 6; outputDelta += 4; }
                else if (d.internalise <= 25) { depthDelta -= 6; outputDelta -= 4; coachKey = `coach_r3_nointernalise`; }
                absorbSpend += d.absorb2;

                summaryKey = (d.posture === `hybrid` && d.boundary === `protectjewels`) ? `sum_r3_good` : (ds.ipLeaked ? `sum_r3_leak` : `sum_r3_weak`);
            } else if (round === 4) {
                // The sourcing decision & innovation output (the central LO).
                // Output that reaches the customer beats patents-as-theatre (Common Error 6).
                if (d.focus === `module`) {
                    outputDelta += 12; depthDelta += 4; coachKey = `coach_r4_module`;
                } else if (d.focus === `patents`) {
                    breadthDelta += 4; outputDelta -= 8; coachKey = `coach_r4_patents`;
                } else {
                    outputDelta -= 6; coachKey = `coach_r4_activity`;
                }

                // Real options for the next migration vs locking in or waiting to react.
                if (d.reallocate === `stayagile`) {
                    breadthDelta += 8; coachKey = (d.focus === `module`) ? `coach_r4_agile` : coachKey;
                } else if (d.reallocate === `lockin`) {
                    breadthDelta -= 8; coachKey = `coach_r4_lockin`;
                } else {
                    breadthDelta -= 4; outputDelta -= 2; coachKey = `coach_r4_react`;
                }

                // The board challenge: did you buy output or activity?
                if (d.defend === `output`) {
                    outputDelta += 8; depthDelta += 4;
                } else if (d.defend === `theatre`) {
                    outputDelta -= 8; coachKey = `coach_r4_theatre`;
                } else {
                    outputDelta -= 6; coachKey = `coach_r4_spend`;
                }

                outputDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.focus === `module` && d.defend === `output` && d.reallocate === `stayagile`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (EUR millions). Over-budget is a real penalty.
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            ds.absorbSpend = Math.round(ds.absorbSpend + absorbSpend);
            if (ds.budgetUsed > this.BUDGET_CAP && !ds.overBudget) {
                ds.overBudget = true;
                outputDelta -= 10; depthDelta -= 6;
                coachKey = `coach_overbudget`;
            } else if (ds.budgetUsed > this.BUDGET_CAP) {
                outputDelta -= 4;
            }

            // Apply deltas, bounded 0–100. Headroom kept so late levers still register.
            ds.breadth = Math.max(0, Math.min(100, ds.breadth + breadthDelta));
            ds.depth = Math.max(0, Math.min(100, ds.depth + depthDelta));
            ds.output = Math.max(0, Math.min(100, ds.output + outputDelta));

            ds.breadthHistory.push(Math.round(ds.breadth));
            ds.depthHistory.push(Math.round(ds.depth));
            ds.outputHistory.push(Math.round(ds.output));

            // At the final round, resolve the 9-month sourcing milestone.
            if (round === this.ROUNDS.length) {
                ds.platformWon = ds.output >= this.WIN_THRESHOLD && !ds.overBudget;
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Investment efficiency: output gained over the start, per €M committed.
            const outputGain = Math.max(0, ds.output - this.START.output);
            const efficiency = ds.budgetUsed > 0 ? Math.round((outputGain / ds.budgetUsed) * 100) / 100 : 0;

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                breadth: Math.round(ds.breadth),
                breadthDelta: Math.round(breadthDelta),
                depth: Math.round(ds.depth),
                depthDelta: Math.round(depthDelta),
                output: Math.round(ds.output),
                outputDelta: Math.round(outputDelta),
                budgetUsed: ds.budgetUsed,
                efficiency: efficiency,
                overBudget: ds.overBudget,
                ipLeaked: ds.ipLeaked,
                blackBox: ds.blackBox,
                platformWon: ds.platformWon,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
