            uiManager.bind(`efficiencyDisplay`, `domainState.budgetUsed`, (v) => {
                const ds = window.mySimulation.state.domainState;
                const gain = Math.max(0, (ds.output || 0) - this.START.output);
                const used = Number(v) || 0;
                if (used <= 0) return `—`;
                const eff = Math.round((gain / used) * 100) / 100;
                return eff.toFixed(2);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.knowbasesim-budget-bar`);
                if (bar) bar.classList.toggle(`knowbasesim-budget-over`, Number(v) > this.BUDGET_CAP);
