        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.outputHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                knowbaseChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.breadthHistory },
                        { data: ds.depthHistory },
                        { data: ds.outputHistory }
                    ]
                }
            };
