        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const breadth = Math.round(ds.breadth);
            const depth = Math.round(ds.depth);
            const output = Math.round(ds.output);
            const composite = Math.round(breadth * 0.30 + depth * 0.30 + output * 0.40);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.platformWon;
            const badge = met
                ? `<span class="knowbasesim-cm-badge knowbasesim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="knowbasesim-cm-badge knowbasesim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const riskBadge = s.blackBox
                ? ` <span class="knowbasesim-cm-badge knowbasesim-cm-no">` + T(`cm_blackbox`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const budStr = (typeof s.budgetUsed === `number`) ? `\u20AC` + s.budgetUsed + `M` : String(s.budgetUsed || ``);
            const metrics = ``
                + `<div class="knowbasesim-cm-metric"><span class="knowbasesim-cm-mv">` + Math.round(s.breadth || 0) + `</span><span class="knowbasesim-cm-ml">` + T(`cm_m_breadth`) + `</span></div>`
                + `<div class="knowbasesim-cm-metric"><span class="knowbasesim-cm-mv">` + Math.round(s.depth || 0) + `</span><span class="knowbasesim-cm-ml">` + T(`cm_m_depth`) + `</span></div>`
                + `<div class="knowbasesim-cm-metric"><span class="knowbasesim-cm-mv">` + Math.round(s.output || 0) + `</span><span class="knowbasesim-cm-ml">` + T(`cm_m_output`) + `</span></div>`
                + `<div class="knowbasesim-cm-metric"><span class="knowbasesim-cm-mv">` + budStr + `</span><span class="knowbasesim-cm-ml">` + T(`cm_m_budget`) + `</span></div>`;
            return ``
                + `<div class="knowbasesim-completion">`
                +   `<div class="knowbasesim-cm-head">`
                +     `<div class="knowbasesim-cm-score">` + score + `<span class="knowbasesim-cm-score-max">/100</span></div>`
                +     `<div class="knowbasesim-cm-grade">` + grade + ` ` + badge + riskBadge + `</div>`
                +   `</div>`
                +   `<div class="knowbasesim-cm-metrics">` + metrics + `</div>`
                +   `<div class="knowbasesim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="knowbasesim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const breadth = Math.round(ds.breadth);
            const depth = Math.round(ds.depth);
            const output = Math.round(ds.output);
            const used = ds.budgetUsed;
            const outputGain = Math.max(0, output - this.START.output);
            const efficiency = used > 0 ? Math.round((outputGain / used) * 100) / 100 : 0;

            const won = ds.platformWon;
            const composite = Math.round(breadth * 0.30 + depth * 0.30 + output * 0.40);

            let performanceKey = `grade_narrow`;
            if (won && composite >= 70 && depth >= 55) performanceKey = `grade_reshaped`;
            else if (won && composite >= 60) performanceKey = `grade_won`;
            else if (won) performanceKey = `grade_thin`;
            else if (output >= 45) performanceKey = `grade_close`;
            else if (ds.blackBox) performanceKey = `grade_trophy`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (won && composite >= 70) insights.push(window.mySimulation.t(`insight_reshaped`));
            else if (won) insights.push(window.mySimulation.t(`insight_won`));
            else insights.push(window.mySimulation.t(`insight_lost`));

            if (ds.blackBox) insights.push(window.mySimulation.t(`insight_blackbox`));
            if (ds.ipLeaked) insights.push(window.mySimulation.t(`insight_leak`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (depth < 40) insights.push(window.mySimulation.t(`insight_shallow`));
            if (breadth < 45) insights.push(window.mySimulation.t(`insight_narrow`));
            if (won && efficiency >= 0.35) insights.push(window.mySimulation.t(`insight_efficient`));

            return {
                breadth: breadth,
                depth: depth,
                output: output,
                budgetUsed: used,
                efficiency: efficiency,
                platformWon: won,
                blackBox: ds.blackBox,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.blackBox) return window.mySimulation.t(`hint_blackbox`);
            if (ds.ipLeaked) return window.mySimulation.t(`hint_leak`);
            if (state.currentPeriod >= 2 && ds.output < 30) return window.mySimulation.t(`hint_behind`);
            if (ds.depth < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_depth`);
            if (ds.output >= this.WIN_THRESHOLD && ds.depth >= 55 && ds.breadth >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

