                    warn_urgency_range:     `La urgencia debe ser un porcentaje entre 0 y 100.`,
                    warn_absorb_negative:   `La inversión en capacidad de absorción no puede ser negativa.`,
                    warn_strongholds_negative: `La financiación de las fortalezas no puede ser negativa.`,
                    warn_absorb2_negative:  `El refuerzo de capacidad de absorción no puede ser negativo.`,
                    warn_internalise_range: `El esfuerzo de internalización debe ser un porcentaje entre 0 y 100.`,
